#!/usr/bin/env node
/**
 * Guards the cascade repair in `src/styles/indic-layout-repairs.css`.
 *
 * The design system under `src/design/indic/` is vendored from PDLMS and
 * regenerated by `sync-indic.mjs`, and it is imported AFTER `index.css` — which
 * is where `@tailwind utilities` lives. Tailwind v3 emits utilities as plain
 * rules at that point in the bundle, not as a native `@layer`, so a
 * design-system class and a Tailwind utility that set the same property at the
 * same specificity (0,1,0) are decided purely by source order, and the design
 * system wins.
 *
 * For `position` that is never the intent. Those classes set `position:
 * relative` only so a decorative ::before/::after can anchor to the host. On an
 * element Tailwind already positions, the promotion is redundant — a
 * fixed/absolute/sticky box is already a containing block for its own
 * pseudo-elements — and it silently demotes the element. `.sidebar-toran-top`
 * did exactly that to the app shell's <aside>, unpinning the sidebar and
 * double-offsetting every page's content by 512px.
 *
 * The scope is deliberately `position` only. For other properties the design
 * system winning is usually the intent (`.indic-icon-plinth` really does want
 * inline-flex; `.pill-*` really do want their own background), so widening this
 * check would produce noise rather than bugs.
 *
 * Contract enforced: every class in the synced design system that promotes an
 * element to `position: relative` must be repaired in indic-layout-repairs.css
 * for all three positioning utilities Tailwind can put on the same element.
 *
 * Run: `pnpm --filter @vidyaverse/frontend check:layout-clobbers`
 */

import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const SRC = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..', 'src');

// Synced, un-editable, and imported after @tailwind utilities.
const SYNCED = [
  'design/indic/indic-tokens.css',
  'design/indic/indic-app.css',
  'design/indic/indic-design-system.css',
  'design/indic/indic-fonts.css',
];
const REPAIRS = 'styles/indic-layout-repairs.css';
const UTILITIES = ['fixed', 'absolute', 'sticky'];

/** Every class that sets `position: <value>` on a real element (not a pseudo). */
function positionPromoters(relPath) {
  const file = path.join(SRC, relPath);
  if (!fs.existsSync(file)) return [];
  const css = fs.readFileSync(file, 'utf8').replace(/\/\*[\s\S]*?\*\//g, '');
  const found = [];
  for (const [, selector, body] of css.matchAll(/([^{}]+)\{([^{}]*)\}/g)) {
    const sel = selector.trim();
    if (sel.startsWith('@')) continue;
    const pos = body.match(/(?:^|;)\s*position\s*:\s*([a-z-]+)/);
    if (!pos) continue;
    for (const part of sel.split(',')) {
      const s = part.trim();
      if (s.includes('::')) continue; // the pseudo-element, not its host
      const classes = s.match(/\.[A-Za-z0-9_-]+/g);
      if (!classes) continue;
      found.push({ cls: classes[classes.length - 1].slice(1), value: pos[1], from: relPath });
    }
  }
  return found;
}

/** class -> Set(utility) already repaired. */
function repairedPairs() {
  const file = path.join(SRC, REPAIRS);
  if (!fs.existsSync(file)) {
    console.error(`FAIL  ${REPAIRS} is missing. It is the repair this check guards.`);
    process.exit(1);
  }
  const css = fs.readFileSync(file, 'utf8').replace(/\/\*[\s\S]*?\*\//g, '');
  const map = new Map();
  for (const [, selector, body] of css.matchAll(/([^{}]+)\{([^{}]*)\}/g)) {
    const pos = body.match(/(?:^|;)\s*position\s*:\s*([a-z-]+)/);
    if (!pos) continue;
    for (const part of selector.split(',')) {
      const m = part.trim().match(/^\.([A-Za-z0-9_-]+)\.([A-Za-z0-9_-]+)$/);
      if (!m) continue;
      const [, cls, util] = m;
      if (!UTILITIES.includes(util) || util !== pos[1]) continue;
      if (!map.has(cls)) map.set(cls, new Set());
      map.get(cls).add(util);
    }
  }
  return map;
}

const promoters = SYNCED.flatMap(positionPromoters).filter((p) => p.value === 'relative');
const repaired = repairedPairs();

const gaps = [];
for (const { cls, from } of promoters) {
  const have = repaired.get(cls) ?? new Set();
  const missing = UTILITIES.filter((u) => !have.has(u));
  if (missing.length) gaps.push({ cls, from, missing });
}

const uniquePromoters = new Set(promoters.map((p) => p.cls));
console.log(
  `checked ${uniquePromoters.size} position:relative promoter(s) across ${SYNCED.length} synced stylesheet(s)`,
);

if (!gaps.length) {
  console.log('OK  every promoter is repaired for fixed/absolute/sticky.');
  process.exit(0);
}

console.error('');
console.error('FAIL  The synced Indic design system promotes classes to `position: relative`');
console.error(`      that ${REPAIRS} does not repair. Because that stylesheet loads after`);
console.error('      @tailwind utilities, each of these silently overrides a Tailwind');
console.error('      positioning utility placed on the same element.');
console.error('');
for (const g of gaps) {
  console.error(`  .${g.cls}  (${g.from})  missing: ${g.missing.map((u) => '.' + u).join(', ')}`);
}
console.error('');
console.error(`Fix: add each class to the matching selector list in ${REPAIRS}.`);
process.exit(1);
